-- S7 isolated acceptance: real-shaped Costing route tables (columns exactly as consumed by the REAL, verbatim route-engine
-- functions loaded from supabase/migrations by extract_route_engine.mjs). Synthetic rows only. This replaces the two
-- minimal shim route tables; no Costing master data, trigger or RPC is created or modified in production by any of this.
DROP TABLE IF EXISTS costing.product_process_route CASCADE;
DROP TABLE IF EXISTS costing.production_route_family_route_step CASCADE;
CREATE TABLE public.sub_groups (id integer PRIMARY KEY, product_group_id integer);
CREATE TABLE public.sections (id integer PRIMARY KEY);
CREATE TABLE public.subsections (id integer PRIMARY KEY, section_id integer);
CREATE TABLE public.areas (id integer PRIMARY KEY, section_id integer, subsection_id integer);
CREATE TABLE public.plant_machinery (id integer PRIMARY KEY, section_id integer, subsection_id integer, area_id integer);
ALTER TABLE public.products ADD COLUMN sub_group_id integer;
ALTER TABLE public.activities ADD COLUMN section_id integer, ADD COLUMN sub_section_id integer, ADD COLUMN area_id integer;
CREATE TABLE public.production_batch_size_ref (id integer PRIMARY KEY, product_id integer);
CREATE TABLE costing.production_cost_centre (id bigint PRIMARY KEY, status text NOT NULL DEFAULT 'APPROVED', effective_from date NOT NULL DEFAULT '2020-01-01', effective_to date, pool_scope text NOT NULL DEFAULT 'PRODUCTION');
CREATE TABLE costing.production_route_behaviour (code text PRIMARY KEY, is_active boolean NOT NULL DEFAULT true);
CREATE TABLE costing.production_resource_class (code text PRIMARY KEY, is_active boolean NOT NULL DEFAULT true);
CREATE TABLE costing.production_route_family (id bigint PRIMARY KEY, status text NOT NULL, effective_from date NOT NULL, effective_to date, archived_at timestamptz, allows_release_only_route boolean NOT NULL DEFAULT false);
CREATE TABLE costing.production_route_family_product_map (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id integer NOT NULL, route_family_id bigint NOT NULL REFERENCES costing.production_route_family(id), status text NOT NULL, effective_from date NOT NULL, effective_to date, archived_at timestamptz);
CREATE TABLE costing.production_route_family_product_subgroup_map (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_subgroup_id integer NOT NULL, route_family_id bigint NOT NULL REFERENCES costing.production_route_family(id), status text NOT NULL, effective_from date NOT NULL, effective_to date, archived_at timestamptz);
CREATE TABLE costing.production_route_family_product_group_map (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_group_id integer NOT NULL, route_family_id bigint NOT NULL REFERENCES costing.production_route_family(id), status text NOT NULL, effective_from date NOT NULL, effective_to date, archived_at timestamptz);
CREATE TABLE costing.production_route_family_route (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, route_family_id bigint NOT NULL REFERENCES costing.production_route_family(id), route_version integer NOT NULL DEFAULT 1, status text NOT NULL, effective_from date NOT NULL, effective_to date, archived_at timestamptz, evidence_status text NOT NULL DEFAULT 'MANUAL_COMPLETE');
CREATE TABLE costing.production_route_family_route_step (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, family_route_id bigint NOT NULL REFERENCES costing.production_route_family_route(id), step_key text NOT NULL, sequence_no numeric NOT NULL,
  activity_id integer NOT NULL, cost_centre_id bigint NOT NULL, section_id integer, subsection_id integer, area_id integer, plant_id integer, behaviour_code text NOT NULL, resource_class_code text NOT NULL,
  route_step_scope text NOT NULL, expected_occurrence_count numeric NOT NULL DEFAULT 1, standard_cycle_count numeric NOT NULL DEFAULT 1, is_mandatory boolean NOT NULL DEFAULT true, allows_repeat boolean NOT NULL DEFAULT false,
  allows_skip_with_approval boolean NOT NULL DEFAULT false, production_overhead_scope text NOT NULL DEFAULT 'INCLUDE', direct_labour_scope text NOT NULL DEFAULT 'INCLUDE');
CREATE TABLE costing.product_process_route (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id integer NOT NULL, base_route_family_route_id bigint NOT NULL REFERENCES costing.production_route_family_route(id), batch_size_ref_id integer,
  status text NOT NULL, effective_from date NOT NULL, effective_to date, archived_at timestamptz, evidence_status text NOT NULL DEFAULT 'MANUAL_COMPLETE');
CREATE TABLE costing.product_process_route_override (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_route_id bigint NOT NULL REFERENCES costing.product_process_route(id), operation_type text NOT NULL, base_step_id bigint REFERENCES costing.production_route_family_route_step(id),
  override_step_key text, sequence_no numeric, activity_id integer, cost_centre_id bigint, section_id integer, subsection_id integer, area_id integer, plant_id integer, behaviour_code text, resource_class_code text, route_step_scope text,
  expected_occurrence_count numeric, standard_cycle_count numeric, is_mandatory boolean, allows_repeat boolean, allows_skip_with_approval boolean, production_overhead_scope text, direct_labour_scope text);
GRANT SELECT ON ALL TABLES IN SCHEMA costing TO authenticated;
-- live product_skus carries is_active / is_sample (read by the client)
ALTER TABLE public.product_skus ADD COLUMN is_active boolean NOT NULL DEFAULT true, ADD COLUMN is_sample boolean NOT NULL DEFAULT false;
